package il.co.jewishcalendar.wear.data

/**
 * ברכות קצרות לשעון — הטקסט מועתק אות באות מהאתר (script.js), כדי שיהיה זהה:
 * אשר יצר — buildBirchotHashacharMizrahiPayload / buildBirchotHashacharSfaradPayload (באתר אין אשר יצר באשכנז;
 *   נוסח ספרד זהה מילה במילה לסידור אשכנז בספריא — נבדק 16/10/2026 — ולכן משמש גם לאשכנז),
 * בורא נפשות — מבלוק מעין שלוש, תפילת הדרך — PRAYER_DB["tefillat-haderech"] (בספרד — נוסח אשכנז).
 * שינוי נוסח באתר ⇒ להעתיק מחדש לכאן.
 */
data class Bracha(val key: String, val title: String, val paras: List<String>)

object Brachot {
    private val ASHER_YATZAR_MIZRAHI = "בָּרוּךְ אַתָּה יְהוָֹה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, אֲשֶׁר יָצַר אֶת הָאָדָם בְּחָכְמָה, וּבָרָא בוֹ נְקָבִים נְקָבִים, חֲלוּלִים חֲלוּלִים, גָּלוּי וְיָדוּעַ לִפְנֵי כִסֵּא כְבוֹדֶךָ, שֶׁאִם יִסָּתֵם אֶחָד מֵהֶם, אוֹ אִם יִפָּתֵח אֶחָד מֵהֶם, אֵי אֶפְשָׁר לְהִתְקַיֵּם אַפִלּוּ שָׁעָה אֶחָת. בָּרוּךְ אַתָּה יְהֹוָה, רוֹפֵא כָל־בָּשָׂר וּמַפְלִיא לַעֲשׂוֹת:"
    private val ASHER_YATZAR_SFARD = "בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם אֲשֶׁר יָצַר אֶת הָאָדָם בְּחָכְמָה וּבָֽרָא בוֹ נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים גָּלוּי וְיָדֽוּעַ לִפְנֵי כִסֵּא כְבוֹדֶֽךָ שֶׁאִם יִפָּתֵֽחַ אֶחָד מֵהֶם אוֹ יִסָּתֵם אֶחָד מֵהֶם אִי אֶפְשַׁר לְהִתְקַיֵּם וְלַעֲמֹד לְפָנֶֽיךָ אֲפִילוּ שָׁעָה אֶחָת. בָּרוּךְ אַתָּה יְהֹוָה רוֹפֵא כָל בָּשָׂר וּמַפְלִיא לַעֲשׂוֹת:"
    private val BOREI_NEFASHOT = "בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן, עַל כֹּל מַה שֶּׁבָּרָאתָ לְהַחֲיוֹת בָּהֶם נֶפֶשׁ כָּל חָי. בָּרוּךְ חָי הָעוֹלָמִים."
    private val HADERECH_MIZRAHI = listOf(
        "יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, שֶׁתּוֹלִיכֵנוּ לְשָׁלוֹם וְתַצְעִידֵנוּ לְשָׁלוֹם וְתַדְרִיכֵנוּ לְשָׁלוֹם, וְתַגִּיעֵנוּ לִמְחוֹז חֶפְצֵנוּ לְחַיִּים וּלְשִׂמְחָה וּלְשָׁלוֹם. (וְתַחְזִירֵנוּ לְשָׁלוֹם) וְתַצִּילֵנוּ מִכַּף כָּל אוֹיֵב וְאוֹרֵב וְלִסְטִים וְחַיּוֹת רָעוֹת בַּדֶּרֶךְ, וּמִכָּל מִינֵי פֻּרְעָנֻיּוֹת הַמִּתְרַגְּשׁוֹת לָבוֹא לָעוֹלָם, וְתִשְׁלַח בְּרָכָה בְּכָל מַעֲשֵׂה יָדֵינוּ, וְתִתְּנֵנוּ לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רוֹאֵינוּ, וְתִשְׁמַע כָּל תַּחֲנוּנֵינוּ, כִּי אֵל שׁוֹמֵעַ תְּפִלָּה וְתַחֲנוּן אָתָּה. בָּרוּךְ אַתָּה יְהֹוָה שׁוֹמֵעַ תְּפִלָּה:\\n\\nוַיַּעֲקֹב הָלַךְ לְדַרְכּוֹ, וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים: וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם, מַחֲנֵה אֱלֹהִים זֶה, וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם:\\n\\n(ג' פעמים) וַיִּסָּעוּ, וַיְהִי חִתַּת אֱלֹהִים עַל הֶעָרִים אֲשֶׁר סְבִיבוֹתֵיהֶם, וְלֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב:\\n\\nלִישׁוּעָתְךָ קִוִּיתִי יְהֹוָה (ג' פעמים)\\n\\nיְבָרֶכְךָ יְהֹוָה וְיִשְׁמְרֶךָ: | יָאֵר יְהֹוָה פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ: | יִשָּׂא יְהֹוָה פָּנָיו אֵלֶיךָ, וְיָשֵׂם לְךָ שָׁלוֹם: (ג' פעמים)",
        "סְגֻלָּה בְּצֵאתוֹ לַדֶּרֶךְ",
        "כְּשֶׁיֵּצֵא מִבֵּיתוֹ, יַנִּיחַ יָדוֹ עַל הַמְּזוּזָה וְיֹאמַר:",
        "ה' יִשְׁמֹר צֵאתִי וּבוֹאִי לְחַיִּים וּלְשָׁלוֹם מֵעַתָּה וְעַד עוֹלָם; אֵל שַׁדַּי יְבָרֵךְ אוֹתִי וְיִתֵּן לִי רַחֲמִים.",
        "(מקור: בן איש חי, פרשת כי תבוא)",
    )
    private val HADERECH_ASHKENAZ = listOf(
        "יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, שֶׁתּוֹלִיכֵנוּ לְשָׁלוֹם וְתַצְעִידֵנוּ לְשָׁלוֹם וְתַדְרִיכֵנוּ לְשָׁלוֹם, וְתִסְמְכֵנוּ לְשָׁלוֹם וְתַגִּיעֵנוּ לִמְחוֹז חֶפְצֵנוּ לְחַיִּים וּלְשִׂמְחָה וּלְשָׁלוֹם. וְתַצִּילֵנוּ מִכַּף כָּל אוֹיֵב וְאוֹרֵב וְלִסְטִים וְחַיּוֹת רָעוֹת בַּדֶּרֶךְ, וּמִכָּל מִינֵי פֻּרְעָנֻיּוֹת הַמִּתְרַגְּשׁוֹת לָבוֹא לָעוֹלָם. וְתִשְׁלַח בְּרָכָה בְּכָל מַעֲשֵׂה יָדֵינוּ, וְתִתְּנֵנוּ לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רוֹאֵינוּ. וְתִשְׁמַע קוֹל תַּחֲנוּנֵינוּ, כִּי אֵל שׁוֹמֵעַ תְּפִלָּה וְתַחֲנוּן אָתָּה.\\n\\nבָּרוּךְ אַתָּה יְהֹוָה, שׁוֹמֵעַ תְּפִלָּה.\\n\\n",
        "סְגֻלָּה בְּצֵאתוֹ לַדֶּרֶךְ",
        "\\n\\nכְּשֶׁיֵּצֵא מִבֵּיתוֹ, יַנִּיחַ יָדוֹ עַל הַמְּזוּזָה וְיֹאמַר:",
        "ה' יִשְׁמֹר צֵאתִי וּבוֹאִי לְחַיִּים וּלְשָׁלוֹם מֵעַתָּה וְעַד עוֹלָם; אֵל שַׁדַּי יְבָרֵךְ אוֹתִי וְיִתֵּן לִי רַחֲמִים.\\n(מקור: בן איש חי, פרשת כי תבוא)",
    )

    /** פסקאות: ירידות שורה של המקור (גם \n מילולי שנשאר מתבנית האתר) מפרידות. */
    private fun split(ps: List<String>): List<String> =
        ps.flatMap { it.replace("\\n", "\n").split("\n") }.map { it.trim() }.filter { it.isNotEmpty() }

    fun all(nusach: String): List<Bracha> = listOf(
        Bracha("asher", "אשר יצר", listOf(if (nusach == "mizrahi") ASHER_YATZAR_MIZRAHI else ASHER_YATZAR_SFARD)),
        Bracha("nefashot", "בורא נפשות", listOf(BOREI_NEFASHOT)),
        Bracha("haderech", "תפילת הדרך", split(if (nusach == "mizrahi") HADERECH_MIZRAHI else HADERECH_ASHKENAZ)),
    )
}
